	return 0

ret1:
	return 1

RPCstack:
	/* put a state and value onto the stack */
	if RPCDebug >= 4 {
		__yyfmt__.Printf("char %v in %v\n", RPCTokname(RPCtoken), RPCStatname(RPCstate))
	}

	RPCp++
	if RPCp >= len(RPCS) {
		nyys := make([]RPCSymType, len(RPCS)*2)
		copy(nyys, RPCS)
		RPCS = nyys
	}
	RPCS[RPCp] = RPCVAL
	RPCS[RPCp].yys = RPCstate

